sys_script_include.script:
var UserGroupUtil = Class.create();
UserGroupUtil.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // 1. Função para o Client Script buscar o gerente
    getBaseManager: function() {
        var baseId = this.getParameter('sysparm_base_id');
        if (!baseId) return '';

        var grBase = new GlideRecord('x_1902784_base_a_0_base_registration'); 
        if (grBase.get(baseId)) {
            return grBase.getValue('manager') || '';
        }
        return '';
    },

    // 2. Função para o Reference Qualifier (Lupa)
    getAvailableUsers: function(currentBaseId, groupName) {
        var query = 'active=true';

        // Filtra pelo grupo
        if (groupName) {
            var groupIds = [];
            var grMember = new GlideRecord('sys_user_grmember');
            grMember.addQuery('group.name', groupName);
            grMember.query();

            while (grMember.next()) {
                groupIds.push(grMember.getValue('user'));
            }

            if (groupIds.length === 0) return 'sys_id=NULL';
            query += '^sys_idIN' + groupIds.join(',');
        }

        // Trava de duplicidade (States 2 ou 3)
        if (currentBaseId) {
            var excludedUsers = [];
            var grAlloc = new GlideRecord('x_1902784_base_a_0_base_allocation'); 
            grAlloc.addQuery('base', currentBaseId);
            grAlloc.addQuery('state', 'IN', '2,3'); 
            grAlloc.addNotNullQuery('opened_by');
            grAlloc.query();

            while (grAlloc.next()) {
                excludedUsers.push(grAlloc.getValue('opened_by'));
            }

            if (excludedUsers.length > 0) {
                query += '^sys_idNOT IN' + excludedUsers.join(',');
            }
        }
        return query;
    },

    type: 'UserGroupUtil'
});
